head.script:
scwin.gridView1_onrightbuttonclick = function(row, col) {
    log = "gridView1_onrightbuttonclick call";
    console.log("gridView1_onrightbuttonclick call");
    WebSquare.logger.printLog("gridView1_onrightbuttonclick call");
};
scwin.gridView1_ontextimageclick = function(row, col) {
    console.log("gridView1_ontextimageclick call");
};
scwin.fireOver = function(node) {
    if (document.createEventObject) {
        node.fireEvent('onmouseover');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('mouseover', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.onmouseover == 'function') {
        node.onmouseover();
    }
}
scwin.rightClick = function(id) {
    var node = WebSquare.wUnit.getDomById($p.id + id);
    if (document.createEventObject) {
        node.fireEvent('oncontextmenu');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('contextmenu', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.oncontextmenu == 'function') {
        node.oncontextmenu();
    }
}
scwin.mouseOverBehaviour = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireOver(el);
}
scwin.checkVal = function(id) {
    if (WebSquare.wUnit.getDomById($p.id + id)) {
        return true;
    }
    return false;
}
scwin.checkLog = function(text) {
    var str = WebSquare.logger.getLog();
    if (str.indexOf(text) >= 0) {
        return true;
    } else return false;
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
	WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal('gridView1_cell_0_0')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.mouseOverBehaviour('gridView1_cell_0_0')");
    WebSquare.wUnit.addCommand("set", "scwin.rightClick('gridView1_cell_0_0')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkLog('gridView1_onrightbuttonclick call')", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
